#!/usr/bin/env bash
# deploy-nav-fix.sh — align the mobile "+" button with the other bottom-tab icons
# (no longer a raised FAB). Writes the fixed Nav.tsx, rebuilds frontend, restarts nginx.
set -euo pipefail

cd /opt/wedding-app/frontend/src/components
cp Nav.tsx Nav.tsx.bak 2>/dev/null || true
base64 -d > Nav.tsx <<'B64_NAV'

B64_NAV

echo "== Sanity check =="
grep -cF 'absolute left-1/2 top-1/2' Nav.tsx

echo "== Rebuilding frontend (a few minutes) =="
cd /opt/wedding-app/infra
docker compose -f docker-compose.prod.yml build frontend
docker compose -f docker-compose.prod.yml up -d frontend
docker compose -f docker-compose.prod.yml restart nginx
sleep 10

echo "== Health =="
curl -sk https://localhost:8443/api/v1/health && echo
echo "DONE. Hard-refresh the page on your phone (or clear browser cache) to see the change."